/* Washly service worker — offline app shell (generated by build.js) */
const CACHE='washly-v1-0-0';
const SHELL=["./","index.html","assets/app.91c72b1412.min.js","assets/app.8006d329d3.min.css","manifest.json","assets/icon-192.png","assets/icon-512.png"];
self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(SHELL)).then(()=>self.skipWaiting()));});
self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(ks=>Promise.all(ks.filter(k=>k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()));});
self.addEventListener('fetch',e=>{
  const r=e.request; if(r.method!=='GET') return;
  const u=new URL(r.url); if(u.origin!==self.location.origin) return; // let CDN font pass through
  e.respondWith(caches.match(r).then(hit=>hit||fetch(r).then(res=>{
    if(res&&res.status===200){const cp=res.clone();caches.open(CACHE).then(c=>c.put(r,cp));}
    return res;
  }).catch(()=>caches.match('index.html'))));
});
